public void accept(final METRICS data) {
    // Check if the data is null or not
    if (data == null) {
        return;
    }

    // Get the existing value from the cache
    METRICS existingValue = get(data.getKey());

    // If the existing value is null, add the new data to the cache
    if (existingValue == null) {
        put(data.getKey(), data);
