        return null;
    }

    // Initialize the StringBuilder with the original string length
    StringBuilder sb = new StringBuilder(str.length());

    // Iterate through the characters in the string
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);

        // If the character is a backslash, check if it's escaped
        if (c == '\\') {
            // If the backslash is escaped, add it to the string builder
            if (i > 0 && str.charAt(i - 1) == '\\') {
                sb.append(c);
            }
            // If the backslash is not escaped, check if it's followed by a valid escape sequence
            else if (i + 1 < str.length() && str.charAt(i + 1) == 'n') {
                // If the escape sequence is valid, add a newline character to the string builder
                sb.append('\n');
                // Skip the next character in the string
                i++;
            }
            // If the backslash is not escaped and not followed by a valid escape sequence, throw an exception
            else {
                throw new Exception("Invalid escape sequence in string: " + str);
            }
        }
        // If the character is not a backslash, add it to the string builder
        else {
            sb.append(c);
        }
    }

    // Return the unescaped string
    return sb.toString();
