public int addConstantNameAndType(String name, String descriptor) {
    // Check if the constant pool already contains a similar item
    int index = findNameAndType(name, descriptor);
    if (index != NOT_FOUND) {
        return index;
    }

    // Add a new CONSTANT_NameAndType_info to the constant pool
    index = addConstant(CONSTANT_NameAndType, 0);
    writeShort(nameIndex(name));
    writeShort(descriptorIndex(descriptor));

    return index;
}

private int findNameAndType(String name, String descriptor) {
    for (int i = 1; i < maxPoolSize; i++) {
        if (types[i] == CONSTANT_NameAndType &&
                nameIndex(name) == readShort(i) &&
                descriptorIndex(descriptor) == readShort(i + 1)) {
            return i;
        }
    }
    return NOT_FOUND;
}

