private int utf8Index(String utf8) {
    int index = findUtf8(utf8);
    if (index == NOT_FOUND) {
        index = addConstant(CONSTANT_Utf8, utf8.length());
        writeUtf8(utf8, index);
    }
    return index;
}

private int addConstant(byte type, int length) {
    int index = findEmptySlot();
    if (index == NOT_FOUND) {
        index = maxPoolSize;
        maxPoolSize++;
    }
    types[index] = type;
    lengths[index] = length;
    return index;
}

private int findEmptySlot() {
    for (int i = 1; i < maxPoolSize; i++) {
        if (types[i] == 0) {
            return i;
        }
    }
    return NOT_FOUND;
}

