/**
 * Computes the upper bound for a given key.
 * @param key the key for which the upper bound is to be computed.
 * @return the computed upper bound.
 */
private int computeUpperBound(K key) {
    // Compute the upper bound for the current key
    int upperBound = 0;

    // Iterate over the keys and compute the maximum upper bound
    for (K otherKey : keys) {
        if (otherKey.compareTo(key) > 0) {
            upperBound = Math.max(upperBound, otherKey.hashCode());
        }
    }

    // Return the computed upper bound
    return upperBound;
